"""The order tables (v2/bom/order-5-100.md/.csv and bom/v1/order-5-100.md/.csv) are generated by one command, `bom.py --order`.

Checks: the command regenerates the committed files byte for byte; the totals add up (lines + fees = order total, per board = total / boards)
from the committed CSV alone; the order totals agree with an independent computation, bom.cost(), which the tables do not use; and the
version 1 adapter reports the design and its plain-text BOM equal. Broken once on purpose: raising one catalog price by 1 CNY moves the
regenerated bytes and the totals (see test_regeneration_detects_a_price_change)."""
import csv
import sys
from pathlib import Path

import pytest

AFE = Path(__file__).resolve().parents[1]
BOMDIR = AFE / "v2" / "bom"
sys.path.insert(0, str(BOMDIR))
import bom      # noqa: E402
import order    # noqa: E402

COMMITTED = {"v2": BOMDIR / "order-5-100", "v1": AFE / "bom" / "v1" / "order-5-100"}


def regenerate(tmp, root=BOMDIR):
    out2, out1 = tmp / "v2" / "order-5-100", tmp / "v1" / "order-5-100"
    old = (order.OUT_V2, order.OUT_V1)
    order.OUT_V2, order.OUT_V1 = str(out2), str(out1)
    try:
        bom.main(["--order", "--root", str(root)])
    finally:
        order.OUT_V2, order.OUT_V1 = old
    return {"v2": out2, "v1": out1}


def test_one_command_regenerates_the_committed_files_byte_identically(tmp_path):
    out = regenerate(tmp_path)
    n = 0
    for d in ("v2", "v1"):
        for ext in (".md", ".csv"):
            got, want = Path(str(out[d]) + ext), Path(str(COMMITTED[d]) + ext)
            assert want.exists(), want
            assert got.read_bytes() == want.read_bytes(), "%s differs: rerun `python3 -I hardware/afe-proto/v2/bom/bom.py --order`" % want
            n += 1
    for d, nm in (("v2", order.IDENT + "-bom.csv"), ("v2", order.IDENT + "-cpl.csv"), ("v1", "jlc-bom.csv")):
        got, want = out[d].parent / nm, COMMITTED[d].parent / nm
        assert got.read_bytes() == want.read_bytes(), want
        n += 1
    assert n == 7
    assert not (COMMITTED["v1"].parent / "jlc-cpl.csv").exists()      # v1: no final board, no position source


def rows(path):
    return list(csv.DictReader(open(path, newline="")))


@pytest.mark.parametrize("design", ["v2", "v1"])
def test_totals_add_up_from_the_csv(design):
    rs = rows(str(COMMITTED[design]) + ".csv")
    assert rs
    for B in (5, 100):
        r = [x for x in rs if int(x["boards"]) == B]
        s = lambda sec: sum(float(x["extended_cny"]) for x in r if x["section"] == sec and x["extended_cny"] and "alternative" not in x["price_basis_or_source"])
        tot = {x["refs_or_item"]: float(x["extended_cny"]) for x in r if x["section"] == "total"}
        parts, fees, pcb, owner = s("jlc-part"), s("fee"), s("pcb"), s("owner-fitted")
        assert len([x for x in r if x["section"] == "jlc-part"]) > 20 and owner > 0 and fees > 0 and pcb > 0
        assert abs(parts - tot["JLC parts"]) < 1e-3 and abs(fees - tot["JLC fees"]) < 1e-3 and abs(pcb - tot["PCB"]) < 1e-3
        assert abs(parts + fees + pcb - tot["JLC order total (parts + fees + PCB)"]) < 1e-3
        assert abs(parts + fees + pcb + owner - tot["ORDER TOTAL"]) < 1e-3
        assert abs(tot["ORDER TOTAL"] / B - tot["PER BOARD"]) < 1e-3
        # every priced line: extended = unit x qty per board x boards
        for x in r:
            if x["section"] in ("jlc-part", "owner-fitted") and x["unit_cny"]:
                assert abs(float(x["unit_cny"]) * int(x["qty_per_board"]) * B - float(x["extended_cny"])) < 1e-3 * max(1, int(x["qty_per_board"])), x


@pytest.mark.parametrize("design", ["v2", "v1"])
def test_order_agrees_with_the_engines_own_cost_model(design, tmp_path):
    """bom.cost() is a different code path (per-board, by block); the order tables must land on the same CNY."""
    data = bom.Data(bom.HERE, {})
    flags = []
    if design == "v2": L = bom.lines(data, flags)
    else: L = order.v1_lines(data, flags)[0]
    for B in (5, 100):
        mine = order.build(data, L, B, bom.PCB_RATE)
        eng = bom.cost(data, L, B, [], False, pcb_rate=bom.PCB_RATE)
        assert abs(mine["grand"] / B - eng["total"]) < 1e-6, (design, B, mine["grand"] / B, eng["total"])
        assert mine["orders"] == (1 if B == 5 else 2) and mine["per"] == (5 if B == 5 else 50)


def test_v1_adapter_reports_design_and_bom_txt_equal_and_the_current_design():
    flags = []
    L, dis, bt, _jlc = order.v1_lines(bom.Data(bom.HERE, {}), flags)
    assert dis[0].startswith("none:"), dis
    j = [x for x in L if x["block"] != "owner"]
    assert sum(x["qty"] for x in j) == 99 and len(j) == 33
    r0 = next(x for x in j if x["lcsc"] == "C21189")
    assert r0["qty"] == 16 and "R109" not in r0["ref"].split(",")
    assert bom.BOARD_MM == (100.0, 62.34)


def test_regeneration_detects_a_price_change(tmp_path):
    """The guard must be able to fail: a copy of the data with one ladder raised by 1 CNY regenerates different bytes and a larger total."""
    cat = tmp_path / "catalog.csv"
    text = (BOMDIR / "catalog.csv").read_text()
    new = text.replace("1:3.5;10:2.69;30:2.34;100:1.91", "1:4.5;10:3.69;30:3.34;100:2.91")
    assert new != text
    cat.write_text(new)
    paths = {"catalog": str(cat)}
    d0, d1 = bom.Data(bom.HERE, {}), bom.Data(bom.HERE, paths)
    L0, L1 = bom.lines(d0, []), bom.lines(d1, [])
    a, b = order.build(d0, L0, 5, bom.PCB_RATE), order.build(d1, L1, 5, bom.PCB_RATE)
    assert abs(b["grand"] - a["grand"] - 1.0 * 2 * 5) < 1e-6      # 1 CNY x 2 pieces per board x 5 boards, tier unchanged


# ---- the board is the source: independent count, written with a different method from order.read_board
BOARD = AFE / "v2" / "layout" / "integrated" / "afe-v2-integrated.kicad_pcb"


def board_smt_refs():
    import re
    refs = []
    for blk in BOARD.read_text().split("\n\t(footprint ")[1:]:
        if '(property "Fitted by" "JLC"' not in blk: continue
        attr = re.search(r"\(attr ([^)]*)\)", blk)
        if attr and "dnp" in attr.group(1): continue
        refs.append(re.search(r'\(property "Reference" "([^"]*)"', blk).group(1))
    return sorted(refs)


def placements_equal_board(o, refs):
    return o["placements"] == len(refs)


def test_order_placements_equal_the_boards_smt_footprints():
    data = bom.Data(bom.HERE, {})
    refs = board_smt_refs()
    assert len(refs) >= 90 and any(r.startswith("BR") for r in refs)
    o = order.build(data, order.lines_from_rows(order.smt_rows(order.read_board(str(BOARD))))
                    + order.owner_lines(data, []), 5, bom.PCB_RATE)
    assert placements_equal_board(o, refs)
    # every board designator is in the order lines, in the board's numbering
    listed = sorted(r for j in o["jlc"] for r in j["refs"].split(","))
    assert listed == refs


def test_the_count_check_fails_when_the_bridges_are_dropped():
    """Broken on purpose: the engine's schematic-era list (no bridges) must NOT equal the board; this is the defect the check exists for."""
    data = bom.Data(bom.HERE, {})
    L = [x for x in bom.lines(data, []) if x["block"] != "owner"]
    o = order.build(data, L, 5, bom.PCB_RATE)
    refs = board_smt_refs()
    assert not placements_equal_board(o, refs) and len(refs) - o["placements"] == 13


def test_every_smt_footprint_is_in_the_bom_and_cpl_uploads():
    refs = board_smt_refs()
    bomrows = list(csv.reader(open(BOMDIR / (order.IDENT + "-bom.csv"), newline="")))
    assert bomrows[0] == ["Comment", "Designator", "Footprint", "LCSC Part #"]
    in_bom = sorted(r for row in bomrows[1:] for r in row[1].split(","))
    cpl = list(csv.reader(open(BOMDIR / (order.IDENT + "-cpl.csv"), newline="")))
    assert cpl[0] == ["Designator", "Mid X", "Mid Y", "Layer", "Rotation"]
    in_cpl = sorted(r[0] for r in cpl[1:])
    assert in_bom == refs and in_cpl == refs
    assert all(r[3] == "Top" for r in cpl[1:])
    # owner-fitted and DNP footprints are in neither
    for bad in ("J101", "J601", "MH601", "R514", "TP101"):
        assert bad not in in_bom and bad not in in_cpl


def test_v1_bom_upload_is_the_designs_jlc_list():
    rows = list(csv.reader(open(AFE / "bom" / "v1" / "jlc-bom.csv", newline="")))
    refs = [r for row in rows[1:] for r in row[1].split(",")]
    assert len(refs) == 99 and "R109" not in refs and "R510" not in refs and len([r for r in refs if r in ("R110", "R520", "R410")]) == 3


def test_bom_md_is_regenerated_from_the_same_board_lines_and_agrees_with_the_order(tmp_path):
    """bom.md (the engine report) must carry no second set of lines or totals: same board, same engine, same 100-board per-board total as the order."""
    out = tmp_path / "bom.md"
    bom.main(["--md", str(out)])
    assert out.read_bytes() == (BOMDIR / "bom.md").read_bytes(), "rerun `python3 -I hardware/afe-proto/v2/bom/bom.py --md hardware/afe-proto/v2/bom/bom.md`"
    data = bom.Data(bom.HERE, {})
    L, res, _d, _f = bom.run_board(data)
    o = order.build(data, L, 100, bom.PCB_RATE)
    assert abs(res[100]["lo"]["total"] - o["grand"] / 100) < 1e-6
    placements = res[20]["lo"]["placements"]
    assert placements == len(board_smt_refs())
    text = (BOMDIR / "bom.md").read_text()
    assert "%d / %d" % (placements, res[20]["lo"]["joints"]) in text and "$%.2f" % (o["grand"] / 100 / bom.FX) in text
